package com.cosmicpve.client;
import com.cosmicpve.upgrade.PlayerUpgradesMenu;import net.minecraft.client.gui.GuiGraphics;import net.minecraft.client.gui.screens.inventory.AbstractContainerScreen;import net.minecraft.client.renderer.RenderPipelines;import net.minecraft.network.chat.Component;import net.minecraft.resources.Identifier;import net.minecraft.world.entity.player.Inventory;
public final class PlayerUpgradesScreen extends AbstractContainerScreen<PlayerUpgradesMenu>{private static final Identifier BG=Identifier.withDefaultNamespace("textures/gui/container/generic_54.png");public PlayerUpgradesScreen(PlayerUpgradesMenu m,Inventory i,Component t){super(m,i,t);imageHeight=71;inventoryLabelY=1000;}@Override public void render(GuiGraphics g,int x,int y,float p){super.render(g,x,y,p);renderTooltip(g,x,y);}@Override protected void renderBg(GuiGraphics g,float p,int x,int y){int l=(width-imageWidth)/2,t=(height-imageHeight)/2;g.blit(RenderPipelines.GUI_TEXTURED,BG,l,t,0,0,imageWidth,imageHeight,256,256);}}
